CREATE DATABASE IF NOT EXISTS kursus_db CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE kursus_db;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, telepon VARCHAR(20), password VARCHAR(255) NOT NULL, role ENUM('admin','siswa','pengajar') NOT NULL, aktif TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE kursus (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL, tingkat VARCHAR(50), biaya INT NOT NULL DEFAULT 0, status ENUM('aktif','nonaktif') NOT NULL DEFAULT 'aktif');
CREATE TABLE pendaftaran (id INT AUTO_INCREMENT PRIMARY KEY, siswa_id INT NOT NULL, kursus_id INT NOT NULL, tanggal DATETIME DEFAULT CURRENT_TIMESTAMP, status ENUM('menunggu','diterima','ditolak') NOT NULL DEFAULT 'menunggu', FOREIGN KEY (siswa_id) REFERENCES users(id), FOREIGN KEY (kursus_id) REFERENCES kursus(id));
CREATE TABLE kelas (id INT AUTO_INCREMENT PRIMARY KEY, kursus_id INT NOT NULL, pengajar_id INT NOT NULL, nama VARCHAR(100) NOT NULL, FOREIGN KEY (kursus_id) REFERENCES kursus(id), FOREIGN KEY (pengajar_id) REFERENCES users(id));
CREATE TABLE kelas_siswa (id INT AUTO_INCREMENT PRIMARY KEY, kelas_id INT NOT NULL, siswa_id INT NOT NULL, FOREIGN KEY (kelas_id) REFERENCES kelas(id), FOREIGN KEY (siswa_id) REFERENCES users(id));
CREATE TABLE jadwal (id INT AUTO_INCREMENT PRIMARY KEY, kelas_id INT NOT NULL, tanggal DATE NOT NULL, jam_mulai TIME NOT NULL, jam_selesai TIME NOT NULL, ruang VARCHAR(50) NOT NULL, FOREIGN KEY (kelas_id) REFERENCES kelas(id));
CREATE TABLE pertemuan (id INT AUTO_INCREMENT PRIMARY KEY, jadwal_id INT NOT NULL, tanggal DATE NOT NULL, FOREIGN KEY (jadwal_id) REFERENCES jadwal(id));
CREATE TABLE presensi (id INT AUTO_INCREMENT PRIMARY KEY, pertemuan_id INT NOT NULL, siswa_id INT NOT NULL, status ENUM('Hadir','Izin','Sakit','Alpa') NOT NULL, pengajar_id INT NOT NULL, waktu_catat DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (pertemuan_id) REFERENCES pertemuan(id), FOREIGN KEY (siswa_id) REFERENCES users(id));
CREATE TABLE tagihan (id INT AUTO_INCREMENT PRIMARY KEY, pendaftaran_id INT NOT NULL, jumlah INT NOT NULL, status ENUM('belum_bayar','menunggu_verifikasi','lunas','ditolak') NOT NULL DEFAULT 'belum_bayar', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (pendaftaran_id) REFERENCES pendaftaran(id));
CREATE TABLE pembayaran (id INT AUTO_INCREMENT PRIMARY KEY, tagihan_id INT NOT NULL, bukti VARCHAR(255) NOT NULL, metode VARCHAR(30), tanggal DATETIME DEFAULT CURRENT_TIMESTAMP, catatan_penolakan VARCHAR(255), FOREIGN KEY (tagihan_id) REFERENCES tagihan(id));
